clean:  { soloBg: 'plain', soloImg: '', soloTone: 'light', soloToneInk: '', soloToneA: 5, soloFace: 62, soloBlur: 0, soloRadius: 'round', soloR: 14, soloH: 44, soloShowAv: true, soloShowName: false, soloShowSub: true,  soloShowGo: true, soloFont: 13,   soloEdge: false }
