if (g.cards.some(c => { const v = voiceCardParts(c); return v && v.data === url; })) { dup++; continue; }
const name = String(f.name || '').replace(/\.[^.]+$/, '').replace(/\|+/g, ' ').trim().slice(0, 60) || '语音';
g.cards.push(name + '|||' + url); added++;
